#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> arr(n);
    for (auto &v : arr) cin >> v;
    // Try every number k of left rotations; sorting the rest needs n - cycles swaps.
    int best = n;
    vector<char> seen(n);
    for (int k = 0; k < n; k++) {
        fill(seen.begin(), seen.end(), 0);
        int cycles = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            cycles++;
            int j = i;
            while (!seen[j]) {
                seen[j] = 1;
                int p = j + k;
                if (p >= n) p -= n;
                j = arr[p] - 1;
            }
        }
        best = min(best, k + n - cycles);
    }
    cout << best << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static int nextInt() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        int r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = nextInt();
        // Try every number k of left rotations; sorting the rest needs n - cycles swaps.
        int best = n;
        boolean[] seen = new boolean[n];
        for (int k = 0; k < n; k++) {
            java.util.Arrays.fill(seen, false);
            int cycles = 0;
            for (int i = 0; i < n; i++) {
                if (seen[i]) continue;
                cycles++;
                int j = i;
                while (!seen[j]) {
                    seen[j] = true;
                    int p = j + k;
                    if (p >= n) p -= n;
                    j = arr[p] - 1;
                }
            }
            best = Math.min(best, k + n - cycles);
        }
        System.out.println(best);
    }
}
